import sys,re
for line in sys.stdin:
    if line.startswith('@@'):
        print(line.strip()[:40]); continue
    for m in re.finditer(r'.{0,70}(\[-.*?-\]|\{\+.*?\+\}).{0,70}', line):
        pass
    # print segments with context
    out=[]
    for m in re.finditer(r'(\[-.*?-\]\s*)?\{\+.*?\+\}|\[-.*?-\]', line):
        s=max(0,m.start()-60); e=min(len(line),m.end()+40)
        out.append(line[s:e].strip())
    if out: print('  '+' || '.join(out)[:1800])
" | head -c 40000

